SEP = "|"
QUOTE = "'"


def _split_fields(text):
    fields, field, quoted = [], "", False
    for ch in text:
        if ch == QUOTE:
            quoted = not quoted
            field += ch
        elif ch == SEP and not quoted:
            fields.append(field)
            field = ""
        else:
            field += ch
    if quoted:
        raise ValueError(f"unclosed quote in {text!r}")
    fields.append(field)
    return fields


def _split_key(field):
    quoted = False
    for i, ch in enumerate(field):
        if ch == QUOTE:
            quoted = not quoted
        elif ch == "=" and not quoted:
            return field[:i], field[i + 1:]
    raise ValueError(f"field without '=': {field!r}")


def _unquote(value):
    out, i = "", 1
    while i < len(value):
        ch = value[i]
        if ch == QUOTE:
            if i + 1 < len(value) and value[i + 1] == QUOTE:
                out += QUOTE
                i += 2
                continue
            if value[i + 1:].strip():
                raise ValueError(f"text after closing quote in {value!r}")
            return out
        out += ch
        i += 1
    raise ValueError(f"unclosed quote in {value!r}")


def parse_fields(text):
    """Parse a line like name=Ann| note='hi| there' into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    result = {}
    for field in _split_fields(text):
        if not field.strip():
            continue
        key, value = _split_key(field)
        key = key.strip()
        if not key:
            raise ValueError(f"empty key in {field!r}")
        value = value.strip()
        if value.startswith(QUOTE):
            value = _unquote(value)
