        key, value = _split_key(field)
        key = key.strip()
        if not key:
            raise ValueError(f"empty key in {field!r}")
        value = value.strip()
        if value.startswith(QUOTE):
            value = _unquote(value)
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = value
    return result
